+void KFilePreviewGeneratorPrivate::addOverlays(QPixmap &icon, const QStringList &overlays)
+{
+    if (overlays.isEmpty()) {
+        return;
+    }
+
+    // same sizes as KIconUtils::addOverlays(), but based on the icon size of the view
+    const QSize viewIconSize = m_viewAdapter->iconSize();
+    const int iconSize = qMin(viewIconSize.width(), viewIconSize.height());
+    int overlaySize;
+    if (iconSize < 32) {
+        overlaySize = 8;
+    } else if (iconSize <= 48) {
+        overlaySize = 16;
+    } else if (iconSize <= 64) {
+        overlaySize = 22;
+    } else if (iconSize <= 96) {
+        overlaySize = 32;
+    } else if (iconSize <= 128) {
+        overlaySize = 48;
+    } else {
+        overlaySize = iconSize / 4;
+    }
+
+    const qreal dpr = icon.devicePixelRatio();
+    const QSizeF size = icon.deviceIndependentSize();
+    overlaySize = qMin(overlaySize, qFloor(qMin(size.width(), size.height())));
+    if (overlaySize <= 0) {
+        return;
+    }
+
+    const std::array<Qt::Corner, 4> indexToCorner{
+        Qt::BottomRightCorner,
+        Qt::BottomLeftCorner,
+        Qt::TopLeftCorner,
+        Qt::TopRightCorner,
+    };
+
+    QPainter painter(&icon);
+    const int count = std::min<int>(indexToCorner.size(), overlays.size());
+    for (int i = 0; i < count; ++i) {
+        const QPixmap overlayPixmap = QIcon::fromTheme(overlays.at(i)).pixmap(QSize(overlaySize, overlaySize), dpr);
+        if (overlayPixmap.isNull()) {
+            continue;
+        }
+
+        QPointF startPoint;
+        switch (indexToCorner[i]) {
+        case Qt::BottomRightCorner:
+            startPoint = QPointF(size.width() - overlaySize, size.height() - overlaySize);
+            break;
+        case Qt::BottomLeftCorner:
+            startPoint = QPointF(0, size.height() - overlaySize);
+            break;
+        case Qt::TopLeftCorner:
+            startPoint = QPointF(0, 0);
+            break;
+        case Qt::TopRightCorner:
+            startPoint = QPointF(size.width() - overlaySize, 0);
+            break;
+        }
+        painter.drawPixmap(startPoint, overlayPixmap);
+    }
+}
